mapper.update:
UPDATE  t_delivery
SET
        delivery_order               = #{deliveryOrder},
        modified_at                  = #{modifiedAt},
        modifier_seq                 = #{modifierSeq}
WHERE   delivery_seq                 = #{deliverySeq}

mapper.select:
SELECT

FROM    t_delivery
WHERE   dispatch_seq = #{dispatchSeq}

    AND driver_seq = #{driverSeq}

SELECT delivery_addr_1, total_box_count, completed_box_count, delivery_box_count, collection_box_count, delivery_estimated_start_time, delivery_estimated_end_time, latitude, longitude, CASE WHEN total_box_count = completed_box_count THEN 'Y' ELSE 'N' END AS delivery_completed_yn, CASE WHEN total_box_count = completed_box_count THEN delivery_datetime ELSE NULL END AS delivery_datetime FROM ( SELECT a.delivery_addr_1, SUM(a.box_count) AS total_box_count, SUM(CASE WHEN a.delivery_status_cd IN ('COMPLETED', 'UNCOMPLETED') THEN a.box_count ELSE 0 END) AS completed_box_count, SUM(CASE WHEN a.delivery_type_cd = 'DELIVERY' THEN a.box_count ELSE 0 END) AS delivery_box_count, SUM(CASE WHEN a.delivery_type_cd = 'COLLECTION' THEN a.box_count ELSE 0 END) AS collection_box_count, MAX(a.delivery_estimated_start_time) AS delivery_estimated_start_time, MAX(a.delivery_estimated_end_time) AS delivery_estimated_end_time, MIN(a.latitude) AS latitude, MIN(a.longitude) AS longitude, MIN(a.delivery_order) AS delivery_order, MAX(a.delivery_datetime) AS delivery_datetime FROM t_delivery a WHERE a.driver_seq = #{driverSeq} AND a.dispatch_seq = #{dispatchSeq}
AND a.delivery_addr_1 = #{deliveryAddr1}
GROUP BY a.delivery_addr_1 ) a ORDER BY delivery_order

SELECT a.delivery_seq, a.tracking_num, a.product_name, a.box_count, a.memo, a.security_code, a.delivery_addr_1, a.delivery_addr_2, a.delivery_status_cd, (SELECT com_code_name FROM t_common_code WHERE com_code_group_cd = 'DeliveryStatus' AND com_code_cd = a.delivery_status_cd) AS delivery_status_cd_name, a.delivery_type_cd, (SELECT com_code_name FROM t_common_code WHERE com_code_group_cd = 'DeliveryType' AND com_code_cd = a.delivery_type_cd) AS delivery_type_cd_name, CASE WHEN a.delivery_type_cd = 'DELIVERY' THEN CASE WHEN a.delivery_status_cd = 'COMPLETED' THEN '배송완료' WHEN a.delivery_status_cd = 'UNCOMPLETED' THEN '미배송' ELSE '배송예정' END ELSE CASE WHEN a.delivery_status_cd = 'COMPLETED' THEN '수거완료' WHEN a.delivery_status_cd = 'UNCOMPLETED' THEN '미수거' ELSE '수거예정' END END AS waybill_status_name, a.shooting_impossible_yn, a.shooting_impossible_reason_cd, (SELECT com_code_name FROM t_common_code WHERE com_code_group_cd = 'ShootingImpossibleReason' AND com_code_cd = a.shooting_impossible_reason_cd) AS shooting_impossible_reason_cd_name, a.consignment_location_cd, (SELECT com_code_name FROM t_common_code WHERE com_code_group_cd = 'ConsignmentLocation' AND com_code_cd = a.consignment_location_cd) AS consignment_location_cd_name, a.uncompleted_reason_cd, (SELECT com_code_name FROM t_common_code WHERE com_code_group_cd = 'UncompletedReason' AND com_code_cd = a.uncompleted_reason_cd) AS uncompleted_reason_cd_name, a.delivery_photo_attach_seq, ( SELECT file_full_path FROM t_attach x INNER JOIN t_file y ON x.attach_seq = y.attach_seq WHERE x.attach_seq = a.delivery_photo_attach_seq LIMIT 1 ) AS delivery_photo_full_path FROM t_delivery a WHERE a.driver_seq = #{driverSeq} AND a.dispatch_seq = #{dispatchSeq}
AND a.delivery_addr_1 = #{deliveryAddr1}
ORDER BY a.delivery_order
